package candidate

import (
	"context"
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"net/http"
	"strings"

	"github.com/XUJiahua/enterprise_agent/internal/app"
	"github.com/XUJiahua/enterprise_agent/internal/protocol"
	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgxpool"
)

const operation = "bulk-approve.v3"

func New(ctx context.Context, pool *pgxpool.Pool, fallback http.Handler) (http.Handler, error) {
	approve := func(ctx context.Context, u app.Identity, key string, ids []string) (protocol.Result, bool, error) {
		// NUL is valid UTF-8, but PostgreSQL text cannot represent it. Treat such
		// an ID as an invalid target before creating an idempotency record.
		for _, id := range ids {
			if strings.ContainsRune(id, 0) {
				return protocol.Result{}, false, &protocol.Rejection{Status: http.StatusConflict}
			}
		}

		hash := requestHash(ids)
		responseBytes, err := json.Marshal(protocol.Result{ApprovedIDs: ids})
		if err != nil {
			return protocol.Result{}, false, err
		}

		tx, err := pool.Begin(ctx)
		if err != nil {
			return protocol.Result{}, false, err
		}
		defer tx.Rollback(ctx)

		_, err = tx.Exec(ctx, `SELECT set_config('app.tenant',$1,true),set_config('app.user',$2,true),set_config('app.role',$3,true)`, u.Tenant, u.User, u.Role)
		if err != nil {
			return protocol.Result{}, false, err
		}

		// The unique scope key serializes concurrent requests. If this scope
		// already exists, lock and replay it without touching any Purchase row.
		var inserted bool
		err = tx.QueryRow(ctx, `
			INSERT INTO "ActionRequest" ("tenantId","actorId",operation,key,"requestHash",response)
			VALUES ($1,$2,$3,$4,$5,$6::jsonb)
			ON CONFLICT ("tenantId","actorId",operation,key) DO NOTHING
			RETURNING true`, u.Tenant, u.User, operation, key, hash, string(responseBytes)).Scan(&inserted)
		if err != nil && !errors.Is(err, pgx.ErrNoRows) {
			return protocol.Result{}, false, err
		}
		if !inserted {
			var storedHash string
			var storedResponse []byte
			err = tx.QueryRow(ctx, `SELECT "requestHash", response FROM "ActionRequest"
				WHERE "tenantId"=$1 AND "actorId"=$2 AND operation=$3 AND key=$4 FOR UPDATE`,
				u.Tenant, u.User, operation, key).Scan(&storedHash, &storedResponse)
			if err != nil {
				return protocol.Result{}, false, err
			}
			if storedHash != hash {
				return protocol.Result{}, false, &protocol.Rejection{Status: http.StatusConflict}
			}
			var result protocol.Result
			if err = json.Unmarshal(storedResponse, &result); err != nil {
				return protocol.Result{}, false, fmt.Errorf("invalid stored action response: %w", err)
			}
			if err = tx.Commit(ctx); err != nil {
				return protocol.Result{}, false, err
			}
			return result, true, nil
		}

		rows, err := tx.Query(ctx, `SELECT id FROM "Purchase"
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3
			  AND status='submitted' ORDER BY id FOR UPDATE`, ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		eligible := make([]string, 0, len(ids))
		for rows.Next() {
			var id string
			if err = rows.Scan(&id); err != nil {
				rows.Close()
				return protocol.Result{}, false, err
			}
			eligible = append(eligible, id)
		}
		if err = rows.Err(); err != nil {
			rows.Close()
			return protocol.Result{}, false, err
		}
		rows.Close()
		if len(eligible) != len(ids) {
			return protocol.Result{}, false, &protocol.Rejection{Status: http.StatusConflict}
		}

		tag, err := tx.Exec(ctx, `UPDATE "Purchase" SET status='approved'
			WHERE id=ANY($1::text[]) AND "tenantId"=$2 AND "createdBy"<>$3 AND status='submitted'`,
			ids, u.Tenant, u.User)
		if err != nil {
			return protocol.Result{}, false, err
		}
		if tag.RowsAffected() != int64(len(ids)) {
			return protocol.Result{}, false, &protocol.Rejection{Status: http.StatusConflict}
		}

		for _, id := range ids {
			_, err = tx.Exec(ctx, `INSERT INTO "ApprovalAudit"
				("tenantId","purchaseId","approvedBy",operation,"idempotencyKey","fromStatus","toStatus")
				VALUES ($1,$2,$3,$4,$5,'submitted','approved')`,
				u.Tenant, id, u.User, operation, key)
			if err != nil {
				return protocol.Result{}, false, err
			}
		}
		if err = tx.Commit(ctx); err != nil {
			return protocol.Result{}, false, err
		}
		return protocol.Result{ApprovedIDs: ids}, false, nil
	}
	return protocol.HTTP(approve, fallback), nil
}

func requestHash(ids []string) string {
	h := sha256.New()
	_, _ = h.Write([]byte(operation + "\n"))
	for _, id := range ids {
		_, _ = fmt.Fprintf(h, "%d:%s", len([]byte(id)), id)
	}
	return hex.EncodeToString(h.Sum(nil))
}

